// Encarts publicitaires : visuels FICTIFS (jeu « Battle Master — Barthyl le Moine », appli « ChatCoquin », personnages inventés). Aucune régie : à remplacer plus tard.
// Configuration de la pub vidéo fictive avant l’aperçu du PDF
var AD_VIDEO_S = 15; // durée totale de la pub, en secondes
var AD_SKIP_S = 5;   // délai avant « Passer la pub », en secondes
(function () {
  'use strict';
  var IMG = 'data:image/jpeg;base64,';
  var CHAT = 'data:image/jpeg;base64,';
  var V_BATTLE = 'data:image/jpeg;base64,';
  var V_CHAT = 'data:image/jpeg;base64,';
  var ADS = [
    { src: IMG, alt: 'Exemple de publicité fictive pour un jeu vidéo médiéval fantastique', msg: 'Exemple de pub fictive : ce jeu n’existe pas, l’encart ne mène nulle part.' },
    { src: CHAT, alt: 'Exemple de publicité fictive pour une application de discussion', msg: 'Exemple de pub fictive : cette appli n’existe pas, l’encart ne mène nulle part.' }
  ];
  var ROTATE_MS = 8000;
  var img = document.querySelector('.adslot .adimg'), hit = document.querySelector('.adslot .adhit'), msg = document.querySelector('.adslot .admsg');
  window.KryptaxAd = { img: IMG, videoS: AD_VIDEO_S, skipS: AD_SKIP_S, slides: [V_BATTLE, V_CHAT] };
  if (img) img.src = IMG;
  if (hit && msg) hit.addEventListener('click', function () { msg.hidden = !msg.hidden; });
  // Bandeaux verticaux (PC uniquement, masqués par CSS en dessous de 1024 px)
  var rl = document.querySelector('.adrail-l .adrimg'), rr = document.querySelector('.adrail-r .adrimg');
  if (rl) rl.src = V_CHAT;
  if (rr) rr.src = V_BATTLE;
  // Smartphone : l’encart unique alterne entre les deux pubs fictives (fondu doux, sans fondu si mouvement réduit)
  if (!img) return;
  var i = 0, rm = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
  function show(k) { var a = ADS[k]; img.src = a.src; img.alt = a.alt; if (msg) msg.textContent = a.msg; }
  setInterval(function () {
    if (document.hidden) return;
    i = (i + 1) % ADS.length;
    if (rm && rm.matches) { show(i); return; }
    img.classList.add('adfade');
    setTimeout(function () { show(i); img.classList.remove('adfade'); }, 450);
  }, ROTATE_MS);
})();
